        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Work and daily-function impact"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Missed 3 days of work last month because she felt too overwhelmed to face the class; struggles with marking and planning and spends weekends recovering."
      }
    },
