        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Alcohol and drug use"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No alcohol or drug issues reported."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Coffee consumption"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Drinks 3–4 coffees per school day and thinks this might be making anxiety worse."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-15",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-15",
        "status": "final",
        "code": {
          "text": "Housing circumstances and perceived safety"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports a noisy, mouldy share house and unstable lease, feels unsafe there, and says these circumstances increase anxiety. Requests support for more stable housing."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-16",
